function dmFriendlyLobby(){
  const panels=Array.from(dmLobby.querySelectorAll(':scope > section')),tabs=document.createElement('nav');tabs.setAttribute('aria-label','Разделы подготовки');tabs.style.cssText='display:flex;flex-wrap:wrap;gap:8px;margin:16px 0';
  const labels=['Отряд','Боссы','Добыча','Правила'],buttons=[];
  function select(index){dmLobby.dataset.dmTab=String(index);panels.forEach((panel,i)=>{panel.hidden=i!==index;});buttons.forEach((button,i)=>{button.setAttribute('aria-pressed',String(i===index));button.style.borderColor=i===index?'#f0cf81':'#716044';button.style.background=i===index?'#574329':'#251f16';});}
  labels.forEach((label,index)=>{const button=gearButton(label,()=>select(index));button.style.cssText='min-height:44px;flex:1;padding:10px 14px;color:#f6e4bb;border:1px solid #716044;border-radius:8px';buttons.push(button);tabs.append(button);});
  panels[0].before(tabs);select(Math.min(3,Number(dmLobby.dataset.dmTab)||0));
  const footer=dmLobby.querySelector('footer');footer.style.cssText='position:sticky;bottom:0;display:flex;justify-content:flex-end;padding:12px 0;background:#251f16;border-top:1px solid #716044';
  const start=footer.querySelector('[data-dm-start]');start.style.cssText='min-height:48px;padding:12px 24px;font-size:16px;background:#66502a;color:#fff1ce;border:1px solid #e0b75c;border-radius:8px';
  const note=document.createElement('p');note.textContent='Выбери соратников. Когда будешь готов — начинай забег.';note.style.cssText='margin:8px 0;color:#e0cfad';tabs.before(note);
}
